declarations.type:
∀ {State : ℕ → Type} {base : State 0} {step : (N : ℕ) → State N → State (N + 1)}
  {sound : ∀ (N : ℕ) (a : State N), GRWTSK.NumberTheory.Zeta.Riemann.RHThrough N} {State_1 : ℕ → Type}
  {base_1 : State_1 0} {step_1 : (N : ℕ) → State_1 N → State_1 (N + 1)}
  {sound_1 : ∀ (N : ℕ) (a : State_1 N), GRWTSK.NumberTheory.Zeta.Riemann.RHThrough N},
  { State := State, base := base, step := step, sound := sound } =
      { State := State_1, base := base_1, step := step_1, sound := sound_1 } →
    State = State_1 ∧ base ≍ base_1 ∧ step ≍ step_1
